const response = $input.first().json;

let parsed = {};

try {
  // AI Agent normalmente retorna o resultado em "output"
  let content = response.output ?? response.text ?? response.content;

  // Fallback caso venha no formato OpenAI
  if (!content && response.choices?.[0]?.message?.content) {
    content = response.choices[0].message.content;
  }

  if (typeof content === "string") {
    // Remove possíveis blocos markdown
    content = content
      .replace(/^```json\s*/i, "")
      .replace(/^```\s*/i, "")
      .replace(/```\s*$/i, "")
      .trim();

    parsed = JSON.parse(content);
  } else if (typeof content === "object" && content !== null) {
    parsed = content;
  }

} catch (e) {
  parsed = {
    parse_error: e.message,
    raw_response: response
  };
}

const prevData = $("Sanitizar Dados e Gerar ID do Projeto").first().json.data;
const apiKey = $("Sanitizar Dados e Gerar ID do Projeto").first().json.apiKey;

return [{
  json: {
    data: prevData,
    apiKey,
    strategistOutput: parsed
  }
}];

