  objetivo_campanhas: raw.objetivo_campanhas || "",
  meta_anuncios: raw.meta_anuncios || "",
  investimento_anuncios: raw.investimento_anuncios || "",
  contas_anuncios: raw.contas_anuncios || "",

  // REGIÃO
  regiao_anuncios: raw.regiao_anuncios || "",
  formas_pagamento: raw.formas_pagamento || "",
  datas_promocoes: raw.datas_promocoes || "",

  // PALAVRAS-CHAVE
  palavras_positivas: raw.palavras_positivas || "",
  palavras_negativas: raw.palavras_negativas || "",

  // ESTRUTURA
  estrutura_organizacional: raw.estrutura_organizacional || "",
  cargo_responsavel: raw.cargo_responsavel || "",
  numero_funcionarios: raw.numero_funcionarios || "",
  contato_responsavel: raw.contato_responsavel || "",

  // CANAIS
  canais: raw.canais || []
};

return [
  {
    json: {
      data,
      project_id: projectId
    }
  }
];

